/* Eigene Abschlussaufgaben: keine amtliche Prüfung und kein automatischer Freitextkorrektor. */
(()=>{const D=globalThis.FRENCH_COURSE;Object.assign(D.exams,{"final1": {"id": "final1-exam", "label": "Gesamtabfrage M1–M9", "title": "Was du aus dem ganzen Lernweg verbinden kannst", "kind": "final", "minutes": "35–45", "intro": "24 neue Aufgaben: 22 geschlossene Aufgaben mit je einem Punkt und zwei eigene Texte mit zusammen bis zu 20 selbst eingeschätzten Punkten. Die beiden Punktarten werden nicht zu einer Schulnote verrechnet. Alle Themen M1–M9 kommen vor.", "sections": [{"id": "read", "title": "A · Den Text verstehen", "note": "Nutze die neue Szene oben. Bedeutungen darfst du nachschauen."}, {"id": "grammar", "title": "B · Sätze passend aufbauen", "note": "Achte auf Rolle, Anzahl, Aussageabsicht und die ausdrücklich verlangte Form."}, {"id": "writing", "title": "C · Schrift und Lautregeln", "note": "Schriftliche Entscheidungen; hier wird keine gesprochene Aussprache bewertet."}, {"id": "text", "title": "D · Mit eigenen Worten", "note": "Zwei Texte mit Kriterien. Nach dem Abgeben selbst anhand der Stufen 0/1/2 einschätzen."}], "scene": {"intro": "Zoé und Adam sind neu im erfundenen Viertel. Lies die Informationen. Hilfen dürfen bei allen Aufgaben benutzt werden.", "lines": [["Zoé", "Salut ! Je m’appelle Zoé. J’ai quatorze ans. Je suis de Lyon. J’habite à Berlin. Je suis en sixième A.", "Hallo! Ich heiße Zoé. Ich bin vierzehn. Ich komme aus Lyon, wohne in Berlin und gehe in die 6. Klasse A."], ["Adam", "Moi, c’est Adam. Je suis d’Avignon. J’habite à Berlin. Je suis en sixième B. J’aime la musique, mais je n’aime pas le sport.", "Ich bin Adam. Ich komme aus Avignon, wohne in Berlin und gehe in die 6. Klasse B. Ich mag Musik, aber keinen Sport."]], "caption": "Zoé und Emma sind in diesen Rollen Mädchen, Adam ist ein Junge. Das Viertel hat eine Bäckerei und mehrere Kinos."}, "questions": [{"type": "choice", "prompt": "Zoé sagt Je m’appelle Zoé. Wen meint je?", "options": ["Zoé selbst", "Den angesprochenen Gast", "Alle Personen zusammen"], "answer": 0, "why": "Je meint immer die aktuell sprechende Person, hier Zoé.", "support": "Je m’appelle = ich heiße", "hints": ["Welche Aussageabsicht und welche Angaben stehen in der Aufgabe?", "Vergleiche den passenden Baustein mit dem erklärten Beispiel."], "lesson": "m1-l1", "section": "read", "points": 1, "id": "final1-e1"}, {"type": "choice", "prompt": "Was unterscheidet Zoés Herkunft und Wohnort?", "options": ["Sie kommt aus Lyon und wohnt in Berlin.", "Sie kommt aus Berlin und wohnt in Lyon.", "Herkunft und Wohnort müssen gleich sein."], "answer": 0, "why": "Je suis de Lyon nennt die Herkunft; j’habite à Berlin den Wohnort.", "support": "de = aus; habiter à = wohnen in", "hints": ["Welche Aussageabsicht und welche Angaben stehen in der Aufgabe?", "Vergleiche den passenden Baustein mit dem erklärten Beispiel."], "lesson": "m6-l1", "section": "read", "points": 1, "id": "final1-e2"}, {"type": "choice", "prompt": "Zoé und Adam sind en sixième, aber in A beziehungsweise B. Was ist belegt?", "options": ["Sie besuchen dieselbe konkrete Klasse.", "Sie sind in derselben Stufe, aber verschiedenen Gruppen.", "Sie wohnen sicher in verschiedenen Städten."], "answer": 1, "why": "Sixième nennt die Stufe, A/B unterscheidet die konkrete Gruppe.", "support": "sixième ≈ 6. Klasse", "hints": ["Welche Aussageabsicht und welche Angaben stehen in der Aufgabe?", "Vergleiche den passenden Baustein mit dem erklärten Beispiel."], "lesson": "m6-l3", "section": "read", "points": 1, "id": "final1-e3"}, {"type": "choice", "prompt": "Adam mag Musik, aber keinen Sport. Welche Zusammenfassung passt?", "options": ["Zwei Dinge werden gemocht.", "Eine Vorliebe und eine Ablehnung werden gegenübergestellt.", "Adam fragt nach einem Ort."], "answer": 1, "why": "Mais verbindet hier den Gegensatz.", "support": "J’aime la musique, mais je n’aime pas le sport = Ich mag Musik, aber keinen Sport.", "hints": ["Welche Aussageabsicht und welche Angaben stehen in der Aufgabe?", "Vergleiche den passenden Baustein mit dem erklärten Beispiel."], "lesson": "m8-l3", "section": "read", "points": 1, "id": "final1-e4"}, {"type": "short", "prompt": "Ergänze nur den Altersbaustein vor quatorze ans: ___ quatorze ans.", "answers": ["J’ai"], "why": "Alter wird mit j’ai … ans ausgedrückt, nicht mit je suis.", "support": "quatorze = vierzehn; ans = Jahre", "hints": ["Lies die gesuchte Information und die Wortangaben genau.", "Prüfe den Baustein und seine Schreibung am erklärten Beispiel."], "mistakes": [], "lesson": "m1-l4", "section": "grammar", "points": 1, "id": "final1-e5"}, {"type": "slots", "prompt": "Wähle den bestimmten Artikel für die bereitgestellten Einzahlwörter.", "slots": [{"label": "amie (Freundin · féminin · Vokalanfang)", "options": ["la", "l’", "les"], "answer": 1, "feedback": "La wird vor amie zu l’."}, {"label": "parc (Park · masculin · Konsonant)", "options": ["le", "la", "l’"], "answer": 0, "feedback": "Masculin ohne Elision → le."}], "why": "L’amie und le parc unterscheiden sich in Genus und Wortanfang.", "support": "Einzahl; der passende Artikel ist ausdrücklich gesucht.", "hints": ["Prüfe zuerst die Aussageabsicht und die bereitgestellten Angaben.", "Löse die Felder einzeln und lies danach den ganzen Satz."], "lesson": "m2-l3", "section": "grammar", "points": 1, "answerPattern": "amie: {0}; parc: {1}", "id": "final1-e6"}, {"type": "short", "prompt": "Setze la fille in die Mehrzahl mit bestimmtem Artikel.", "answers": ["les filles"], "why": "Im Plural wird la zu les; das Nomen erhält hier -s.", "support": "fille = Mädchen; Plural filles", "hints": ["Lies die gesuchte Information und die Wortangaben genau.", "Prüfe den Baustein und seine Schreibung am erklärten Beispiel."], "mistakes": [], "lesson": "m2-l4", "section": "grammar", "points": 1, "id": "final1-e7"}, {"type": "short", "prompt": "Benenne die zwei Personen Zoé und Adam. Ergänze nur den Anfang: ___ Zoé et Adam.", "answers": ["Ce sont"], "why": "Mehrere verschiedene Namen werden hier mit ce sont benannt.", "support": "et = und; geübtes schriftliches Benennungsmuster", "hints": ["Lies die gesuchte Information und die Wortangaben genau.", "Prüfe den Baustein und seine Schreibung am erklärten Beispiel."], "mistakes": [], "lesson": "m3-l2", "section": "grammar", "points": 1, "id": "final1-e8"}, {"type": "choice", "prompt": "Warum heißt es mon amie Zoé und nicht ma amie Zoé?", "options": ["Amie ist dadurch masculin.", "Vor dem Vokalanfang steht hier mon; amie bleibt féminin.", "Zoé sind mehrere Personen."], "answer": 1, "why": "Mon vor femininem amie vermeidet hier zwei aufeinanderfolgende Vokale. Das Genus ändert sich nicht.", "support": "amie = Freundin · féminin · Singular", "hints": ["Welche Aussageabsicht und welche Angaben stehen in der Aufgabe?", "Vergleiche den passenden Baustein mit dem erklärten Beispiel."], "lesson": "m3-l3", "section": "grammar", "points": 1, "id": "final1-e9"}, {"type": "slots", "prompt": "Ersetze Zoé et Emma durch ein Pronomen und ergänze être.", "slots": [{"label": "Pronomen", "options": ["elles", "ils", "nous"], "answer": 0, "feedback": "Laut Rolle sind beide Mädchen, die Sprecherin gehört nicht dazu."}, {"label": "être", "options": ["est", "sommes", "sont"], "answer": 2, "feedback": "Zur dritten Person Plural gehört sont."}], "why": "Elles sont à Berlin.", "support": "Zoé und Emma = zwei Mädchen, über die eine dritte Person spricht; à Berlin = in Berlin", "hints": ["Prüfe zuerst die Aussageabsicht und die bereitgestellten Angaben.", "Löse die Felder einzeln und lies danach den ganzen Satz."], "lesson": "m4-l2", "section": "grammar", "points": 1, "answerPattern": "{0} {1} à Berlin.", "id": "final1-e10"}, {"type": "short", "prompt": "Zoé meint mit on ihre Gruppe. Ergänze: On ___ dans le parc.", "answers": ["est"], "why": "On verlangt est, auch wenn mehrere Menschen gemeint sind.", "support": "on = hier wir; dans le parc = im Park", "hints": ["Lies die gesuchte Information und die Wortangaben genau.", "Prüfe den Baustein und seine Schreibung am erklärten Beispiel."], "mistakes": [], "lesson": "m4-l5", "section": "grammar", "points": 1, "id": "final1-e11"}, {"type": "choice", "prompt": "Du fragst einen einzelnen Erwachsenen höflich Vous êtes de Lyon ?. Er antwortet allein über sich.", "options": ["Oui, vous êtes de Lyon.", "Oui, je suis de Lyon.", "Oui, nous sommes de Lyon."], "answer": 1, "why": "Ein höfliches vous in der Frage macht die Antwort nicht zur Wir-Aussage.", "support": "oui = ja; de Lyon = aus Lyon", "hints": ["Welche Aussageabsicht und welche Angaben stehen in der Aufgabe?", "Vergleiche den passenden Baustein mit dem erklärten Beispiel."], "lesson": "m5-l3", "section": "grammar", "points": 1, "id": "final1-e12"}, {"type": "choice", "prompt": "Du suchst nur Adams Wohnort. Welche Frage passt?", "options": ["Tu habites où ?", "Tu as quel âge ?", "C’est qui ?"], "answer": 0, "why": "Où im Wohnortbaustein sucht einen Ort.", "support": "Wohnort: habiter; Alter: âge; Person: qui", "hints": ["Welche Aussageabsicht und welche Angaben stehen in der Aufgabe?", "Vergleiche den passenden Baustein mit dem erklärten Beispiel."], "lesson": "m5-l2", "section": "grammar", "points": 1, "id": "final1-e13"}, {"type": "short", "prompt": "Setze nur den Herkunftsbaustein vor Avignon: Je suis ___ Avignon.", "answers": ["d’"], "why": "De wird vor dem Vokalanfang von Avignon zu d’.", "support": "Je suis de/d’ = ich komme aus", "hints": ["Lies die gesuchte Information und die Wortangaben genau.", "Prüfe den Baustein und seine Schreibung am erklärten Beispiel."], "mistakes": [], "lesson": "m6-l1", "section": "grammar", "points": 1, "id": "final1-e14"}, {"type": "choice", "prompt": "Welche schriftliche Form passt zur eigenen Wohnstadt?", "options": ["Je habite Berlin.", "J’habite à Berlin.", "Je suis de Berlin."], "answer": 1, "why": "J’habite à nennt den Wohnort; vor h muet wird je verkürzt.", "support": "Berlin ist laut Rolle der Wohnort, nicht die gesuchte Herkunft.", "hints": ["Welche Aussageabsicht und welche Angaben stehen in der Aufgabe?", "Vergleiche den passenden Baustein mit dem erklärten Beispiel."], "lesson": "m6-l2", "section": "grammar", "points": 1, "id": "final1-e15"}, {"type": "slots", "prompt": "Es gibt eine Bäckerei und mehrere Kinos. Führe sie neu ein.", "slots": [{"label": "Ausdruck", "options": ["Ils y a", "Il y a", "Ce sont"], "answer": 1, "feedback": "Il y a bleibt hier auch bei mehreren Dingen unverändert."}, {"label": "eine Bäckerei", "options": ["un boulangerie", "une boulangerie", "l’boulangerie"], "answer": 1, "feedback": "Boulangerie ist féminin."}, {"label": "mehrere Kinos", "options": ["des cinémas", "les cinémas", "un cinéma"], "answer": 0, "feedback": "Die neue unbestimmte Mehrzahl wird mit des eingeführt."}], "why": "Il y a une boulangerie et des cinémas.", "support": "boulangerie = Bäckerei · féminin; cinéma = Kino · masculin; cinémas = Kinos; et = und", "hints": ["Prüfe zuerst die Aussageabsicht und die bereitgestellten Angaben.", "Löse die Felder einzeln und lies danach den ganzen Satz."], "lesson": "m7-l3", "section": "grammar", "points": 1, "answerPattern": "{0} {1} et {2}.", "id": "final1-e16"}, {"type": "choice", "prompt": "Zoé zeigt das eine bereits besprochene Hotel und benennt es.", "options": ["C’est l’hôtel.", "Il y a des hôtels.", "Ce sont les hôtels."], "answer": 0, "why": "C’est benennt hier das bestimmte einzelne Hotel. Die anderen Sätze ändern Funktion oder Anzahl.", "support": "hôtel = Hotel · masculin · Singular · h muet", "hints": ["Welche Aussageabsicht und welche Angaben stehen in der Aufgabe?", "Vergleiche den passenden Baustein mit dem erklärten Beispiel."], "lesson": "m7-l4", "section": "grammar", "points": 1, "id": "final1-e17"}, {"type": "short", "prompt": "Verneine vollständig schriftlich: J’aime la musique.", "answers": ["Je n’aime pas la musique.", "Je n’aime pas la musique"], "why": "Je bleibt vor n’ ausgeschrieben; n’ und pas umschließen aime. La musique bleibt.", "support": "la musique = Musik allgemein; nicht mögen = ne/n’ … pas", "hints": ["Lies die gesuchte Information und die Wortangaben genau.", "Prüfe den Baustein und seine Schreibung am erklärten Beispiel."], "mistakes": [], "lesson": "m8-l2", "section": "grammar", "points": 1, "id": "final1-e18"}, {"type": "short", "prompt": "Frage nach einer Wahl: Tu aimes la musique ___ le sport ? Ergänze nur oder.", "answers": ["ou"], "why": "Ou ohne Akzent verbindet Möglichkeiten. Où mit Akzent bedeutet wo.", "support": "la musique = Musik; le sport = Sport", "hints": ["Lies die gesuchte Information und die Wortangaben genau.", "Prüfe den Baustein und seine Schreibung am erklärten Beispiel."], "mistakes": [], "lesson": "m8-l3", "section": "grammar", "points": 1, "id": "final1-e19"}, {"type": "short", "prompt": "Erhalte den Akzent in der Ortsfrage: Tu habites ___ ?", "answers": ["où"], "why": "Der Sinn ist wo, daher où mit accent grave.", "support": "wo = où; oder = ou", "hints": ["Lies die gesuchte Information und die Wortangaben genau.", "Prüfe den Baustein und seine Schreibung am erklärten Beispiel."], "mistakes": [], "lesson": "m9-l2", "section": "writing", "points": 1, "id": "final1-e20"}, {"type": "choice", "prompt": "Welche Lautzuordnung passt zu rue (Straße) und roue (Rad)?", "options": ["u in rue → [y], ungefähr ü; ou in roue → [u], ungefähr u", "Beide klingen immer gleich.", "Ou besteht hier aus zwei getrennten Vokalen."], "answer": 0, "why": "In diesen Beispielen unterscheiden sich französisches u und ou.", "support": "Lautzeichen sind nur Hilfen, kein vollständiges Lautalphabet.", "hints": ["Welche Aussageabsicht und welche Angaben stehen in der Aufgabe?", "Vergleiche den passenden Baustein mit dem erklärten Beispiel."], "lesson": "m9-l3", "section": "writing", "points": 1, "id": "final1-e21"}, {"type": "choice", "prompt": "Welche Verbindung ist korrekt beschrieben?", "options": ["Nach et entsteht immer eine t-Liaison.", "Les amis hat hier z-Liaison; nach et keine t-Liaison.", "Liaison wird als neues Wort geschrieben."], "answer": 1, "why": "Les amis wird verbunden gesprochen, aber weiterhin mit Wortabstand geschrieben. Et hat keine t-Liaison.", "support": "les amis = die Freunde; et = und", "hints": ["Welche Aussageabsicht und welche Angaben stehen in der Aufgabe?", "Vergleiche den passenden Baustein mit dem erklärten Beispiel."], "lesson": "m9-l4", "section": "writing", "points": 1, "id": "final1-e22"}, {"type": "open", "prompt": "Spiele Zoé. Verfasse eine kurze Vorstellung: Name, Alter 14, Herkunft Lyon, Wohnort Berlin, Klasse sixième A. Ergänze: Du magst Katzen, aber keinen Sport.", "support": "Je m’appelle = ich heiße; j’ai quatorze ans = ich bin 14; je suis de = ich komme aus; j’habite à = ich wohne in; en sixième A = 6. Klasse A; les chats = Katzen; le sport = Sport; mais = aber.", "sample": "Je m’appelle Zoé. J’ai quatorze ans. Je suis de Lyon. J’habite à Berlin. Je suis en sixième A. J’aime les chats, mais je n’aime pas le sport.", "criteria": ["Name und Alter sind als eigene Angaben verständlich.", "Herkunft Lyon und Wohnort Berlin sind richtig unterschieden.", "Die Klasse sixième A ist angegeben.", "Katzen werden gemocht und Sport mit vollständigem n’ … pas abgelehnt.", "Ich-Rolle, Artikel, Akzente und Apostrophe sind überprüft."], "why": "Das ist eine mögliche Fassung. Vergleiche deinen Text an den vier Kriterien. Die Selbstbewertung zählt getrennt von automatisch geprüften Antworten.", "rubric": [["Noch nicht erfüllt: Die geforderte Information fehlt oder ist inhaltlich unpassend.", "Ein Teil der geforderten Information ist verständlich.", "Die gesamte Information dieses Kriteriums ist verständlich und passend angegeben."], ["Noch nicht erfüllt: Die geforderte Information fehlt oder ist inhaltlich unpassend.", "Ein Teil der geforderten Information ist verständlich.", "Die gesamte Information dieses Kriteriums ist verständlich und passend angegeben."], ["Noch nicht erfüllt: Die geforderte Information fehlt oder ist inhaltlich unpassend.", "Ein Teil der geforderten Information ist verständlich.", "Die gesamte Information dieses Kriteriums ist verständlich und passend angegeben."], ["Noch nicht erfüllt: Die geforderte Information fehlt oder ist inhaltlich unpassend.", "Ein Teil der geforderten Information ist verständlich.", "Die gesamte Information dieses Kriteriums ist verständlich und passend angegeben."], ["Noch nicht erfüllt: Die geforderte Information fehlt oder ist inhaltlich unpassend.", "Ein Teil der geforderten Information ist verständlich.", "Die gesamte Information dieses Kriteriums ist verständlich und passend angegeben."]], "lesson": "m8-l4", "section": "text", "id": "final1-e23", "language": "fr"}, {"type": "open", "prompt": "Sprachmittlung auf Deutsch: Erkläre einer Person ohne Französischkenntnisse Adams Nachricht. Nenne Herkunft, Wohnort, Klasse, beide Vorliebenangaben und was es im Viertel gibt.", "support": "Adam: Je suis d’Avignon. J’habite à Berlin. Je suis en sixième B. J’aime la musique, mais je n’aime pas le sport. Dans le quartier, il y a une boulangerie et des cinémas. Hilfen: quartier = Viertel; boulangerie = Bäckerei; cinémas = Kinos; übrige Bausteine stehen in der Szene.", "sample": "Adam kommt aus Avignon und wohnt in Berlin. Er geht in die 6. Klasse B. Er mag Musik, aber keinen Sport. Im Viertel gibt es eine Bäckerei und mehrere Kinos.", "criteria": ["Herkunft und Wohnort sind richtig wiedergegeben.", "Die Klasse ist richtig genannt.", "Vorliebe und Ablehnung sind ohne Vertauschung erklärt.", "Bäckerei und mehrere Kinos sind als Angebot im Viertel genannt.", "Die deutsche Nachricht ist verständlich; keine unbelegten Angaben wurden ergänzt."], "why": "Das ist eine mögliche Fassung. Vergleiche deinen Text an den vier Kriterien. Die Selbstbewertung zählt getrennt von automatisch geprüften Antworten.", "rubric": [["Noch nicht erfüllt: Die geforderte Information fehlt oder ist inhaltlich unpassend.", "Ein Teil der geforderten Information ist verständlich.", "Die gesamte Information dieses Kriteriums ist verständlich und passend angegeben."], ["Noch nicht erfüllt: Die geforderte Information fehlt oder ist inhaltlich unpassend.", "Ein Teil der geforderten Information ist verständlich.", "Die gesamte Information dieses Kriteriums ist verständlich und passend angegeben."], ["Noch nicht erfüllt: Die geforderte Information fehlt oder ist inhaltlich unpassend.", "Ein Teil der geforderten Information ist verständlich.", "Die gesamte Information dieses Kriteriums ist verständlich und passend angegeben."], ["Noch nicht erfüllt: Die geforderte Information fehlt oder ist inhaltlich unpassend.", "Ein Teil der geforderten Information ist verständlich.", "Die gesamte Information dieses Kriteriums ist verständlich und passend angegeben."], ["Noch nicht erfüllt: Die geforderte Information fehlt oder ist inhaltlich unpassend.", "Ein Teil der geforderten Information ist verständlich.", "Die gesamte Information dieses Kriteriums ist verständlich und passend angegeben."]], "lesson": "m6-l4", "section": "text", "id": "final1-e24", "language": "de"}]}, "mock1": {"id": "mock1-exam", "label": "Probeklausur A", "title": "Ein Schulfest in Nantes", "kind": "mock", "minutes": "45–60", "intro": "20 neue Aufgaben · 60 Übungspunkte: 40 automatisch geprüfte Punkte und bis zu 20 selbst eingeschätzte Schreibpunkte. Bei mehrteiligen Auswahlaufgaben zählt jedes richtige Feld einen Punkt. Keine Schulnote und keine amtliche Zeitvorgabe. Du darfst die bereitgestellten Wort- und Bedeutungshilfen nutzen.", "sections": [{"id": "read", "title": "A · Den Text verstehen", "note": "Nutze die neue Szene oben. Bedeutungen darfst du nachschauen."}, {"id": "grammar", "title": "B · Sätze passend aufbauen", "note": "Achte auf Rolle, Anzahl, Aussageabsicht und die ausdrücklich verlangte Form."}, {"id": "writing", "title": "C · Schrift und Lautregeln", "note": "Schriftliche Entscheidungen; hier wird keine gesprochene Aussprache bewertet."}, {"id": "text", "title": "D · Mit eigenen Worten", "note": "Zwei Texte mit Kriterien. Nach dem Abgeben selbst anhand der Stufen 0/1/2 einschätzen."}], "scene": {"intro": "Neue Situation: Lucie und Malik treffen sich bei einem Schulfest. Alle Figuren und Ortsangaben dieser Geschichte sind erfunden.", "lines": [["Lucie", "Salut ! Je m’appelle Lucie. J’ai douze ans. Je suis de Lille. J’habite à Nantes. Je suis en sixième A.", "Sprachhilfe: salut = hallo; je m’appelle = ich heiße; j’ai … ans = ich bin … Jahre alt; douze = 12; je suis de/d’ = ich komme aus; j’habite à = ich wohne in; en sixième ≈ in der 6. Klasse."], ["Lucie", "J’aime la nature, mais je n’aime pas les jeux vidéo. Dans le quartier, il y a deux gares et un café.", "Sprachhilfe: j’aime = ich mag; mais = aber; je n’aime pas = ich mag nicht; la nature = Natur; les jeux vidéo = Videospiele; dans le quartier = im Viertel; il y a = es gibt; deux = zwei; gares = Bahnhöfe; café = Café."], ["Malik", "Moi, c’est Malik. Je suis en sixième B.", "Sprachhilfe: moi, c’est = ich bin; je suis en sixième = ich gehe in die 6. Klasse."]], "caption": "Lucie und Inès sind laut Rolle Mädchen. Die bereitgestellten Bedeutungshilfen gehören zur Aufgabe; der Schwerpunkt ist Grammatik, kein Vokabeltest."}, "questions": [{"type": "choice", "prompt": "Wo wohnt Lucie laut Text?", "options": ["Lille", "Nantes", "Das steht nicht im Text."], "answer": 1, "why": "J’habite à Nantes nennt den Wohnort. de Lille nennt dagegen die Herkunft.", "support": "habiter à = wohnen in; je suis de/d’ = ich komme aus", "hints": ["Welche Aussageabsicht und welche Angaben stehen in der Aufgabe?", "Vergleiche den passenden Baustein mit dem erklärten Beispiel."], "lesson": "m6-l2", "section": "read", "points": 2, "id": "mock1-e1"}, {"type": "choice", "prompt": "Was ist über die Klassen von Lucie und Malik belegt?", "options": ["Gleiche konkrete Klasse.", "Gleiche Stufe, aber verschiedene Gruppen.", "Unterschiedliche Länder."], "answer": 1, "why": "Sixième A und sixième B nennen dieselbe Stufe mit unterschiedlichen Gruppen.", "support": "sixième ≈ 6. Klasse", "hints": ["Welche Aussageabsicht und welche Angaben stehen in der Aufgabe?", "Vergleiche den passenden Baustein mit dem erklärten Beispiel."], "lesson": "m6-l3", "section": "read", "points": 2, "id": "mock1-e2"}, {"type": "choice", "prompt": "Welche Vorlieben hat Lucie?", "options": ["Natur ja; Videospiele nein.", "Videospiele ja; Natur nein.", "Beide werden abgelehnt."], "answer": 0, "why": "Der positive Teil steht vor mais, die Ablehnung mit n’ … pas danach.", "support": "aimer = mögen; mais = aber; ne/n’ … pas = nicht", "hints": ["Welche Aussageabsicht und welche Angaben stehen in der Aufgabe?", "Vergleiche den passenden Baustein mit dem erklärten Beispiel."], "lesson": "m8-l2", "section": "read", "points": 2, "id": "mock1-e3"}, {"type": "choice", "prompt": "Was sagt die Szene über die Anzahl der Orte?", "options": ["Ein Bahnhof und mehrere Cafés.", "Mehrere Bahnhöfe und ein Café.", "Es gibt keine Orte."], "answer": 1, "why": "Deux gares gibt zwei Orte an; un café einen einzelnen.", "support": "deux = zwei; il y a = es gibt; die deutschen Ortsnamen stehen im Text.", "hints": ["Welche Aussageabsicht und welche Angaben stehen in der Aufgabe?", "Vergleiche den passenden Baustein mit dem erklärten Beispiel."], "lesson": "m7-l3", "section": "read", "points": 2, "id": "mock1-e4"}, {"type": "short", "prompt": "Lucie sagt das eigene Alter. Ergänze nur vor douze ans: ___ douze ans.", "answers": ["J’ai"], "why": "Der Altersbaustein lautet j’ai douze ans. Die Person spricht über sich.", "support": "douze = 12; ans = Jahre", "hints": ["Lies die gesuchte Information und die Wortangaben genau.", "Prüfe den Baustein und seine Schreibung am erklärten Beispiel."], "mistakes": [], "lesson": "m1-l4", "section": "grammar", "points": 2, "id": "mock1-e5"}, {"type": "slots", "prompt": "Wähle nur die bestimmten Artikel vor den bereitgestellten Einzahlwörtern.", "slots": [{"label": "amie (Freundin · féminin · Vokal)", "options": ["la", "l’", "les"], "answer": 1, "feedback": "Vor amie wird la elidiert."}, {"label": "gare (Bahnhof · féminin · Konsonant)", "options": ["le", "la", "l’"], "answer": 1, "feedback": "féminin ohne Elision → la."}], "why": "Genus und Wortanfang entscheiden getrennt. L’ macht ein feminines Nomen nicht masculin.", "support": "Einzahl und bestimmter Artikel sind verlangt.", "hints": ["Prüfe zuerst die Aussageabsicht und die bereitgestellten Angaben.", "Löse die Felder einzeln und lies danach den ganzen Satz."], "lesson": "m2-l3", "section": "grammar", "points": 2, "slotPoints": [1, 1], "answerPattern": "amie: {0}; gare: {1}", "id": "mock1-e6"}, {"type": "short", "prompt": "Benenne Lucie und Malik, zwei verschiedene Personen: ___ Lucie et Malik.", "answers": ["Ce sont"], "why": "Mehrere Namen werden im geübten schriftlichen Muster mit ce sont benannt.", "support": "et = und", "hints": ["Lies die gesuchte Information und die Wortangaben genau.", "Prüfe den Baustein und seine Schreibung am erklärten Beispiel."], "mistakes": [], "lesson": "m3-l2", "section": "grammar", "points": 2, "id": "mock1-e7"}, {"type": "slots", "prompt": "Eine dritte Person spricht über Lucie und Inès. Wähle Pronomen und Verb.", "slots": [{"label": "Pronomen", "options": ["elles", "ils", "nous"], "answer": 0, "feedback": "Die vorgegebenen Personen sind zwei Mädchen. Die sprechende Person gehört nicht dazu."}, {"label": "être", "options": ["est", "sommes", "sont"], "answer": 2, "feedback": "Zur dritten Person Plural gehört sont."}], "why": "Elles sont dans la même classe.", "support": "Lucie und Inès = Mädchen; dans la même classe = in derselben Klasse", "hints": ["Prüfe zuerst die Aussageabsicht und die bereitgestellten Angaben.", "Löse die Felder einzeln und lies danach den ganzen Satz."], "lesson": "m4-l2", "section": "grammar", "points": 2, "slotPoints": [1, 1], "answerPattern": "{0} {1} dans la même classe.", "id": "mock1-e8"}, {"type": "short", "prompt": "Malik meint mit on sich und Lucie: On ___ ensemble.", "answers": ["est"], "why": "On verlangt die Form est der dritten Person Singular; die Bedeutung kann eine Gruppe sein.", "support": "ensemble = zusammen", "hints": ["Lies die gesuchte Information und die Wortangaben genau.", "Prüfe den Baustein und seine Schreibung am erklärten Beispiel."], "mistakes": [], "lesson": "m4-l5", "section": "grammar", "points": 2, "id": "mock1-e9"}, {"type": "choice", "prompt": "Eine einzelne Lehrkraft wird mit Vous êtes de Paris ? höflich angesprochen und antwortet allein über sich.", "options": ["Oui, je suis de Paris.", "Oui, nous sommes de Paris.", "Oui, vous êtes de Paris."], "answer": 0, "why": "Die antwortende Einzelperson sagt je suis. Höfliches vous ist kein Beleg für eine Gruppe.", "support": "oui = ja; de Paris = aus Paris", "hints": ["Welche Aussageabsicht und welche Angaben stehen in der Aufgabe?", "Vergleiche den passenden Baustein mit dem erklärten Beispiel."], "lesson": "m5-l3", "section": "grammar", "points": 2, "id": "mock1-e10"}, {"type": "short", "prompt": "Lucie nennt die eigene Herkunft. Ergänze nur vor Lille: Je suis ___ Lille.", "answers": ["de"], "why": "Herkunft steht hier mit de; vor Vokalanfang wird daraus d’.", "support": "Ich komme aus Lille. Gesucht ist nur der Baustein de/d’.", "hints": ["Lies die gesuchte Information und die Wortangaben genau.", "Prüfe den Baustein und seine Schreibung am erklärten Beispiel."], "mistakes": [], "lesson": "m6-l1", "section": "grammar", "points": 2, "id": "mock1-e11"}, {"type": "slots", "prompt": "Führe ein Café und mehrere Bahnhöfe neu ein.", "slots": [{"label": "Ausdruck", "options": ["Ce sont", "Ils y a", "Il y a"], "answer": 2, "feedback": "Für eine Existenzangabe steht il y a."}, {"label": "ein Café", "options": ["un café", "une café"], "answer": 0, "feedback": "café ist masculin."}], "why": "Il y a un café et des gares.", "support": "café = Café · masculin; et des gares = und mehrere Bahnhöfe ist als fester Schlussteil gegeben.", "hints": ["Prüfe zuerst die Aussageabsicht und die bereitgestellten Angaben.", "Löse die Felder einzeln und lies danach den ganzen Satz."], "lesson": "m7-l2", "section": "grammar", "points": 2, "slotPoints": [1, 1], "answerPattern": "{0} {1} et des gares.", "id": "mock1-e12"}, {"type": "short", "prompt": "Verneine vollständig schriftlich: J’aime les jeux vidéo.", "answers": ["Je n’aime pas les jeux vidéo.", "Je n’aime pas les jeux vidéo"], "why": "Je n’aime pas umschließt aime mit n’ und pas. Der bestimmte Artikel bleibt bei dieser allgemeinen Vorliebe.", "support": "les jeux vidéo = Videospiele; nicht = ne/n’ … pas", "hints": ["Lies die gesuchte Information und die Wortangaben genau.", "Prüfe den Baustein und seine Schreibung am erklärten Beispiel."], "mistakes": [], "lesson": "m8-l2", "section": "grammar", "points": 2, "id": "mock1-e13"}, {"type": "choice", "prompt": "Welche Frage sucht eine Wahl zwischen Natur und Sport?", "options": ["Tu aimes la nature où le sport ?", "Tu aimes la nature ou le sport ?", "Tu habites la nature ?"], "answer": 1, "why": "Ou ohne Akzent bedeutet oder. Die Frage bleibt in der Du-Rolle.", "support": "la nature = Natur; le sport = Sport; où = wo; ou = oder", "hints": ["Welche Aussageabsicht und welche Angaben stehen in der Aufgabe?", "Vergleiche den passenden Baustein mit dem erklärten Beispiel."], "lesson": "m8-l3", "section": "grammar", "points": 2, "id": "mock1-e14"}, {"type": "slots", "prompt": "Drei kurze Ergänzungen zum Schriftbild.", "slots": [{"label": "Ortsbaustein: Il est ___ Paris.", "options": ["a", "à", "ou"], "answer": 1, "feedback": "À bezeichnet hier den Ort; a bedeutet hat."}, {"label": "Ortsfrage: Tu habites ___ ?", "options": ["ou", "où", "et"], "answer": 1, "feedback": "Où bedeutet wo."}, {"label": "Café schreibt man mit …", "options": ["cafe", "café", "cafè"], "answer": 1, "feedback": "É hat einen accent aigu."}], "why": "Il est à Paris. Tu habites où ? Café endet auf é.", "support": "il est = er ist; a = hat; à = in; où = wo; ou = oder; café = Café", "hints": ["Prüfe zuerst die Aussageabsicht und die bereitgestellten Angaben.", "Löse die Felder einzeln und lies danach den ganzen Satz."], "lesson": "m9-l2", "section": "writing", "points": 3, "slotPoints": [1, 1, 1], "answerPattern": "Ort: {0}; Ortsfrage: {1}; Schreibung: {2}", "id": "mock1-e15"}, {"type": "slots", "prompt": "Ordne die drei vorgegebenen Lautregeln zu.", "slots": [{"label": "rue (Straße): u klingt hier …", "options": ["[y] ≈ ü", "[u] ≈ u", "[e]"], "answer": 0, "feedback": "U in rue steht für [y]."}, {"label": "roue (Rad): ou klingt hier …", "options": ["[y] ≈ ü", "[u] ≈ u", "[ɛ]"], "answer": 1, "feedback": "Ou in roue steht für [u]."}, {"label": "France und dans enthalten …", "options": ["[ɔ̃] wie in non", "[ɑ̃]", "ein zusätzliches deutliches ng"], "answer": 1, "feedback": "An/en wird in diesen Beispielen als Nasalvokal [ɑ̃] gesprochen."}], "why": "Rue [ʁy], roue [ʁu]; France und dans haben [ɑ̃]. Nasalität ist Teil des Vokals.", "support": "France = Frankreich; dans = in; non = nein; Lautzeichen sind Hilfen.", "hints": ["Prüfe zuerst die Aussageabsicht und die bereitgestellten Angaben.", "Löse die Felder einzeln und lies danach den ganzen Satz."], "lesson": "m9-l3", "section": "writing", "points": 3, "slotPoints": [1, 1, 1], "answerPattern": "rue: {0}; roue: {1}; France/dans: {2}", "id": "mock1-e16"}, {"type": "slots", "prompt": "Prüfe drei Regelentscheidungen zu c/ç und stummen Endungen.", "slots": [{"label": "garçon (Junge) braucht …", "options": ["cédille am c", "accent aigu am a", "keinen Zusatz"], "answer": 0, "feedback": "Ç erhält den s-Laut vor o."}, {"label": "c in café (Café) klingt hier …", "options": ["s", "k", "z"], "answer": 1, "feedback": "Vor a klingt c im Beispiel café wie k."}, {"label": "Das End-s in Paris ist normalerweise …", "options": ["ein deutliches s", "stumm", "ein zusätzliches n"], "answer": 1, "feedback": "Das s in Paris wird normalerweise nicht gesprochen."}], "why": "Garçon mit ç, café mit k-Laut; das End-s von Paris bleibt geschrieben, aber stumm.", "support": "Die richtigen Vorlagen garçon, café und Paris stehen absichtlich dabei.", "hints": ["Prüfe zuerst die Aussageabsicht und die bereitgestellten Angaben.", "Löse die Felder einzeln und lies danach den ganzen Satz."], "lesson": "m9-l4", "section": "writing", "points": 3, "slotPoints": [1, 1, 1], "answerPattern": "garçon: {0}; café: {1}; Paris: {2}", "id": "mock1-e17"}, {"type": "slots", "prompt": "Verbindung und Buchstabieren: drei Entscheidungen.", "slots": [{"label": "les amis (die Freunde) hat hier …", "options": ["eine z-Liaison", "eine t-Liaison", "nie eine Verbindung"], "answer": 0, "feedback": "Les + Vokalanfang amis wird hier mit z verbunden."}, {"label": "Nach et (und) gibt es …", "options": ["immer t-Liaison", "keine t-Liaison", "ein geschriebenes z"], "answer": 1, "feedback": "Et wird nicht mit t-Liaison angeschlossen."}, {"label": "G und J heißen …", "options": ["G = ji, J = gé", "G = gé, J = ji", "beide gé"], "answer": 1, "feedback": "G heißt gé, J heißt ji."}], "why": "Liaison verändert keine Schreibweise. Buchstabennamen sind nicht automatisch Laute im Wort.", "support": "Laut- und Schriftregeln aus M9, keine Audioaufgabe.", "hints": ["Prüfe zuerst die Aussageabsicht und die bereitgestellten Angaben.", "Löse die Felder einzeln und lies danach den ganzen Satz."], "lesson": "m9-l1", "section": "writing", "points": 3, "slotPoints": [1, 1, 1], "answerPattern": "les amis: {0}; et: {1}; Alphabet: {2}", "id": "mock1-e18"}, {"type": "open", "prompt": "Erkläre Lucies Nachricht auf Deutsch für eine Person, die kein Französisch lernt. Nenne Name/Alter, Herkunft/Wohnort, Klasse, Vorliebe/Ablehnung und die Orte mit Anzahl. Schreibe sinngemäß, keine Wort-für-Wort-Übersetzung.", "support": "Nutze die Szene oben. douze = 12; sixième A ≈ 6. Klasse A; la nature = Natur; les jeux vidéo = Videospiele; deux gares = zwei Bahnhöfe; un café = ein Café.", "sample": "Lucie ist 12 Jahre alt, kommt aus Lille und wohnt in Nantes. Sie geht in die 6. Klasse A, mag Natur, aber mag Videospiele nicht. Im Viertel gibt es zwei Bahnhöfe und ein Café.", "criteria": ["Name Lucie und Alter 12 sind richtig wiedergegeben.", "Herkunft Lille und Wohnort Nantes sind richtig getrennt.", "Die Klasse sixième A ist sinngemäß wiedergegeben.", "Natur wird gemocht, Videospiele abgelehnt.", "Zwei Bahnhöfe und ein Café sind verständlich mit richtiger Anzahl genannt."], "why": "Das ist eine mögliche Fassung. Vergleiche deinen Text an den vier Kriterien. Die Selbstbewertung zählt getrennt von automatisch geprüften Antworten.", "rubric": [["Noch nicht erfüllt: Die geforderte Information fehlt oder ist inhaltlich unpassend.", "Ein Teil der geforderten Information ist verständlich.", "Die gesamte Information dieses Kriteriums ist verständlich und passend angegeben."], ["Noch nicht erfüllt: Die geforderte Information fehlt oder ist inhaltlich unpassend.", "Ein Teil der geforderten Information ist verständlich.", "Die gesamte Information dieses Kriteriums ist verständlich und passend angegeben."], ["Noch nicht erfüllt: Die geforderte Information fehlt oder ist inhaltlich unpassend.", "Ein Teil der geforderten Information ist verständlich.", "Die gesamte Information dieses Kriteriums ist verständlich und passend angegeben."], ["Noch nicht erfüllt: Die geforderte Information fehlt oder ist inhaltlich unpassend.", "Ein Teil der geforderten Information ist verständlich.", "Die gesamte Information dieses Kriteriums ist verständlich und passend angegeben."], ["Noch nicht erfüllt: Die geforderte Information fehlt oder ist inhaltlich unpassend.", "Ein Teil der geforderten Information ist verständlich.", "Die gesamte Information dieses Kriteriums ist verständlich und passend angegeben."]], "lesson": "m6-l4", "section": "text", "id": "mock1-e19", "language": "de"}, {"type": "open", "prompt": "Spiele Malik und schreibe einen kurzen französischen Vorstellungstext mit sechs bis acht Sätzen. Fakten: Name Malik; Alter 13; Herkunft Berlin; Wohnort Nantes; Klasse sixième B; du magst Sport, aber keine Katzen. Im Viertel gibt es zwei Bahnhöfe und ein Café. Verbinde die beiden Vorliebenangaben mit mais.", "support": "Bausteine: Je m’appelle; j’ai treize ans (13); je suis de; j’habite à; je suis en sixième B; le sport = Sport; les chats = Katzen; mais = aber; il y a = es gibt; deux gares = zwei Bahnhöfe; un café = ein Café; et = und.", "sample": "Je m’appelle Malik. J’ai treize ans. Je suis de Berlin. J’habite à Nantes. Je suis en sixième B. J’aime le sport, mais je n’aime pas les chats. Dans le quartier, il y a deux gares et un café.", "criteria": ["Name und Alter der Rolle Malik sind verständlich in Ich-Form genannt.", "Herkunft Berlin, Wohnort Nantes und Klasse sixième B sind richtig getrennt.", "Sport ja und Katzen nein sind mit mais verbunden; n’ … pas ist vollständig.", "Il y a führt die Orte mit richtiger Anzahl und passenden bereitgestellten Gruppen ein.", "Der Text hängt verständlich zusammen; Person/Verb, Artikel, Apostrophe und Akzente wurden überprüft."], "why": "Das ist eine mögliche Fassung. Vergleiche deinen Text an den vier Kriterien. Die Selbstbewertung zählt getrennt von automatisch geprüften Antworten.", "rubric": [["Noch nicht erfüllt: Die geforderte Information fehlt oder ist inhaltlich unpassend.", "Nur Name oder Alter ist korrekt.", "Name und Alter stimmen; je m’appelle und j’ai … ans sind passend verwendet."], ["Noch nicht erfüllt: Die geforderte Information fehlt oder ist inhaltlich unpassend.", "Ein oder zwei der drei Angaben stimmen.", "Herkunft, Wohnort und Klasse stimmen mit passenden Bausteinen."], ["Noch nicht erfüllt: Die geforderte Information fehlt oder ist inhaltlich unpassend.", "Der Sinn ist teils klar, aber Verbinder oder ein Negationsteil fehlt.", "Beide Aussagen stimmen; mais, je n’aime pas und die bestimmten Artikel sind passend."], ["Noch nicht erfüllt: Die geforderte Information fehlt oder ist inhaltlich unpassend.", "Ein Ort oder seine Anzahl ist verständlich; andere Teile fehlen.", "Beide Orte stimmen; il y a bleibt gleich und die genauen Mengen sind passend."], ["Noch nicht erfüllt: Die geforderte Information fehlt oder ist inhaltlich unpassend.", "Weitgehend verständlich, aber mehrere Muster-/Schriftfehler erschweren das Lesen.", "Gut verständlicher Zusammenhang mit überwiegend passenden bekannten Formen und Schriftzeichen; kleinere Fehler sind möglich."]], "lesson": "m8-l4", "section": "text", "id": "mock1-e20", "language": "fr"}]}, "mock2": {"id": "mock2-exam", "label": "Probeklausur B", "title": "Ein neues Viertel in Toulouse", "kind": "mock", "minutes": "45–60", "intro": "20 neue Aufgaben · 60 Übungspunkte: 40 automatisch geprüfte Punkte und bis zu 20 selbst eingeschätzte Schreibpunkte. Bei mehrteiligen Auswahlaufgaben zählt jedes richtige Feld einen Punkt. Keine Schulnote und keine amtliche Zeitvorgabe. Du darfst die bereitgestellten Wort- und Bedeutungshilfen nutzen.", "sections": [{"id": "read", "title": "A · Den Text verstehen", "note": "Nutze die neue Szene oben. Bedeutungen darfst du nachschauen."}, {"id": "grammar", "title": "B · Sätze passend aufbauen", "note": "Achte auf Rolle, Anzahl, Aussageabsicht und die ausdrücklich verlangte Form."}, {"id": "writing", "title": "C · Schrift und Lautregeln", "note": "Schriftliche Entscheidungen; hier wird keine gesprochene Aussprache bewertet."}, {"id": "text", "title": "D · Mit eigenen Worten", "note": "Zwei Texte mit Kriterien. Nach dem Abgeben selbst anhand der Stufen 0/1/2 einschätzen."}], "scene": {"intro": "Neue Situation: Émile und Ana treffen sich bei einem Schulfest. Alle Figuren und Ortsangaben dieser Geschichte sind erfunden.", "lines": [["Émile", "Salut ! Je m’appelle Émile. J’ai treize ans. Je suis d’Avignon. J’habite à Toulouse. Je suis en sixième B.", "Sprachhilfe: salut = hallo; je m’appelle = ich heiße; j’ai … ans = ich bin … Jahre alt; treize = 13; je suis de/d’ = ich komme aus; j’habite à = ich wohne in; en sixième ≈ in der 6. Klasse."], ["Émile", "J’aime la musique, mais je n’aime pas le shopping. Dans le quartier, il y a deux musées et une boulangerie.", "Sprachhilfe: j’aime = ich mag; mais = aber; je n’aime pas = ich mag nicht; la musique = Musik; le shopping = Einkaufen; dans le quartier = im Viertel; il y a = es gibt; deux = zwei; musées = Museen; boulangerie = Bäckerei."], ["Ana", "Moi, c’est Ana. Je suis en sixième A.", "Sprachhilfe: moi, c’est = ich bin; je suis en sixième = ich gehe in die 6. Klasse."]], "caption": "Émile und Hugo sind laut Rolle Jungen. Die bereitgestellten Bedeutungshilfen gehören zur Aufgabe; der Schwerpunkt ist Grammatik, kein Vokabeltest."}, "questions": [{"type": "choice", "prompt": "Wo wohnt Émile laut Text?", "options": ["Avignon", "Toulouse", "Das steht nicht im Text."], "answer": 1, "why": "J’habite à Toulouse nennt den Wohnort. d’Avignon nennt dagegen die Herkunft.", "support": "habiter à = wohnen in; je suis de/d’ = ich komme aus", "hints": ["Welche Aussageabsicht und welche Angaben stehen in der Aufgabe?", "Vergleiche den passenden Baustein mit dem erklärten Beispiel."], "lesson": "m6-l2", "section": "read", "points": 2, "id": "mock2-e1"}, {"type": "choice", "prompt": "Was ist über die Klassen von Émile und Ana belegt?", "options": ["Gleiche konkrete Klasse.", "Gleiche Stufe, aber verschiedene Gruppen.", "Unterschiedliche Länder."], "answer": 1, "why": "Sixième B und sixième A nennen dieselbe Stufe mit unterschiedlichen Gruppen.", "support": "sixième ≈ 6. Klasse", "hints": ["Welche Aussageabsicht und welche Angaben stehen in der Aufgabe?", "Vergleiche den passenden Baustein mit dem erklärten Beispiel."], "lesson": "m6-l3", "section": "read", "points": 2, "id": "mock2-e2"}, {"type": "choice", "prompt": "Welche Vorlieben hat Émile?", "options": ["Musik ja; Einkaufen nein.", "Einkaufen ja; Musik nein.", "Beide werden abgelehnt."], "answer": 0, "why": "Der positive Teil steht vor mais, die Ablehnung mit n’ … pas danach.", "support": "aimer = mögen; mais = aber; ne/n’ … pas = nicht", "hints": ["Welche Aussageabsicht und welche Angaben stehen in der Aufgabe?", "Vergleiche den passenden Baustein mit dem erklärten Beispiel."], "lesson": "m8-l2", "section": "read", "points": 2, "id": "mock2-e3"}, {"type": "choice", "prompt": "Was sagt die Szene über die Anzahl der Orte?", "options": ["Ein Museum und mehrere Bäckereien.", "Mehrere Museen und eine Bäckerei.", "Es gibt keine Orte."], "answer": 1, "why": "Deux musées gibt zwei Orte an; une boulangerie einen einzelnen.", "support": "deux = zwei; il y a = es gibt; die deutschen Ortsnamen stehen im Text.", "hints": ["Welche Aussageabsicht und welche Angaben stehen in der Aufgabe?", "Vergleiche den passenden Baustein mit dem erklärten Beispiel."], "lesson": "m7-l3", "section": "read", "points": 2, "id": "mock2-e4"}, {"type": "short", "prompt": "Émile sagt das eigene Alter. Ergänze nur vor treize ans: ___ treize ans.", "answers": ["J’ai"], "why": "Der Altersbaustein lautet j’ai treize ans. Die Person spricht über sich.", "support": "treize = 13; ans = Jahre", "hints": ["Lies die gesuchte Information und die Wortangaben genau.", "Prüfe den Baustein und seine Schreibung am erklärten Beispiel."], "mistakes": [], "lesson": "m1-l4", "section": "grammar", "points": 2, "id": "mock2-e5"}, {"type": "slots", "prompt": "Wähle nur die bestimmten Artikel vor den bereitgestellten Einzahlwörtern.", "slots": [{"label": "amie (Freundin · féminin · Vokal)", "options": ["la", "l’", "les"], "answer": 1, "feedback": "Vor amie wird la elidiert."}, {"label": "musée (Museum · masculin · Konsonant)", "options": ["le", "la", "l’"], "answer": 0, "feedback": "masculin ohne Elision → le."}], "why": "Genus und Wortanfang entscheiden getrennt. L’ macht ein feminines Nomen nicht masculin.", "support": "Einzahl und bestimmter Artikel sind verlangt.", "hints": ["Prüfe zuerst die Aussageabsicht und die bereitgestellten Angaben.", "Löse die Felder einzeln und lies danach den ganzen Satz."], "lesson": "m2-l3", "section": "grammar", "points": 2, "slotPoints": [1, 1], "answerPattern": "amie: {0}; musée: {1}", "id": "mock2-e6"}, {"type": "short", "prompt": "Benenne Émile und Ana, zwei verschiedene Personen: ___ Émile et Ana.", "answers": ["Ce sont"], "why": "Mehrere Namen werden im geübten schriftlichen Muster mit ce sont benannt.", "support": "et = und", "hints": ["Lies die gesuchte Information und die Wortangaben genau.", "Prüfe den Baustein und seine Schreibung am erklärten Beispiel."], "mistakes": [], "lesson": "m3-l2", "section": "grammar", "points": 2, "id": "mock2-e7"}, {"type": "slots", "prompt": "Eine dritte Person spricht über Émile und Hugo. Wähle Pronomen und Verb.", "slots": [{"label": "Pronomen", "options": ["elles", "ils", "nous"], "answer": 1, "feedback": "Die vorgegebenen Personen sind zwei Jungen. Die sprechende Person gehört nicht dazu."}, {"label": "être", "options": ["est", "sommes", "sont"], "answer": 2, "feedback": "Zur dritten Person Plural gehört sont."}], "why": "Ils sont dans le même quartier.", "support": "Émile und Hugo = Jungen; dans le même quartier = in demselben Viertel", "hints": ["Prüfe zuerst die Aussageabsicht und die bereitgestellten Angaben.", "Löse die Felder einzeln und lies danach den ganzen Satz."], "lesson": "m4-l2", "section": "grammar", "points": 2, "slotPoints": [1, 1], "answerPattern": "{0} {1} dans le même quartier.", "id": "mock2-e8"}, {"type": "short", "prompt": "Ana meint mit on sich und Émile: On ___ ensemble.", "answers": ["est"], "why": "On verlangt die Form est der dritten Person Singular; die Bedeutung kann eine Gruppe sein.", "support": "ensemble = zusammen", "hints": ["Lies die gesuchte Information und die Wortangaben genau.", "Prüfe den Baustein und seine Schreibung am erklärten Beispiel."], "mistakes": [], "lesson": "m4-l5", "section": "grammar", "points": 2, "id": "mock2-e9"}, {"type": "choice", "prompt": "Eine einzelne Lehrkraft wird mit Vous êtes de Paris ? höflich angesprochen und antwortet allein über sich.", "options": ["Oui, je suis de Paris.", "Oui, nous sommes de Paris.", "Oui, vous êtes de Paris."], "answer": 0, "why": "Die antwortende Einzelperson sagt je suis. Höfliches vous ist kein Beleg für eine Gruppe.", "support": "oui = ja; de Paris = aus Paris", "hints": ["Welche Aussageabsicht und welche Angaben stehen in der Aufgabe?", "Vergleiche den passenden Baustein mit dem erklärten Beispiel."], "lesson": "m5-l3", "section": "grammar", "points": 2, "id": "mock2-e10"}, {"type": "short", "prompt": "Émile nennt die eigene Herkunft. Ergänze nur vor Avignon: Je suis ___ Avignon.", "answers": ["d’"], "why": "Herkunft steht hier mit de; vor Vokalanfang wird daraus d’.", "support": "Ich komme aus Avignon. Gesucht ist nur der Baustein de/d’.", "hints": ["Lies die gesuchte Information und die Wortangaben genau.", "Prüfe den Baustein und seine Schreibung am erklärten Beispiel."], "mistakes": [], "lesson": "m6-l1", "section": "grammar", "points": 2, "id": "mock2-e11"}, {"type": "slots", "prompt": "Führe eine Bäckerei und mehrere Museen neu ein.", "slots": [{"label": "Ausdruck", "options": ["Ce sont", "Ils y a", "Il y a"], "answer": 2, "feedback": "Für eine Existenzangabe steht il y a."}, {"label": "eine Bäckerei", "options": ["un boulangerie", "une boulangerie"], "answer": 1, "feedback": "boulangerie ist féminin."}], "why": "Il y a une boulangerie et des musées.", "support": "boulangerie = Bäckerei · féminin; et des musées = und mehrere Museen ist als fester Schlussteil gegeben.", "hints": ["Prüfe zuerst die Aussageabsicht und die bereitgestellten Angaben.", "Löse die Felder einzeln und lies danach den ganzen Satz."], "lesson": "m7-l2", "section": "grammar", "points": 2, "slotPoints": [1, 1], "answerPattern": "{0} {1} et des musées.", "id": "mock2-e12"}, {"type": "short", "prompt": "Verneine vollständig schriftlich: J’aime le shopping.", "answers": ["Je n’aime pas le shopping.", "Je n’aime pas le shopping"], "why": "Je n’aime pas umschließt aime mit n’ und pas. Der bestimmte Artikel bleibt bei dieser allgemeinen Vorliebe.", "support": "le shopping = Einkaufen; nicht = ne/n’ … pas", "hints": ["Lies die gesuchte Information und die Wortangaben genau.", "Prüfe den Baustein und seine Schreibung am erklärten Beispiel."], "mistakes": [], "lesson": "m8-l2", "section": "grammar", "points": 2, "id": "mock2-e13"}, {"type": "choice", "prompt": "Welche Frage sucht eine Wahl zwischen Musik und Sport?", "options": ["Tu aimes la musique où le sport ?", "Tu aimes la musique ou le sport ?", "Tu habites la musique ?"], "answer": 1, "why": "Ou ohne Akzent bedeutet oder. Die Frage bleibt in der Du-Rolle.", "support": "la musique = Musik; le sport = Sport; où = wo; ou = oder", "hints": ["Welche Aussageabsicht und welche Angaben stehen in der Aufgabe?", "Vergleiche den passenden Baustein mit dem erklärten Beispiel."], "lesson": "m8-l3", "section": "grammar", "points": 2, "id": "mock2-e14"}, {"type": "slots", "prompt": "Drei kurze Ergänzungen zum Schriftbild.", "slots": [{"label": "Ortsbaustein: Il est ___ Paris.", "options": ["a", "à", "ou"], "answer": 1, "feedback": "À bezeichnet hier den Ort; a bedeutet hat."}, {"label": "Ortsfrage: Tu habites ___ ?", "options": ["ou", "où", "et"], "answer": 1, "feedback": "Où bedeutet wo."}, {"label": "Café schreibt man mit …", "options": ["cafe", "café", "cafè"], "answer": 1, "feedback": "É hat einen accent aigu."}], "why": "Il est à Paris. Tu habites où ? Café endet auf é.", "support": "il est = er ist; a = hat; à = in; où = wo; ou = oder; café = Café", "hints": ["Prüfe zuerst die Aussageabsicht und die bereitgestellten Angaben.", "Löse die Felder einzeln und lies danach den ganzen Satz."], "lesson": "m9-l2", "section": "writing", "points": 3, "slotPoints": [1, 1, 1], "answerPattern": "Ort: {0}; Ortsfrage: {1}; Schreibung: {2}", "id": "mock2-e15"}, {"type": "slots", "prompt": "Ordne die drei vorgegebenen Lautregeln zu.", "slots": [{"label": "rue (Straße): u klingt hier …", "options": ["[y] ≈ ü", "[u] ≈ u", "[e]"], "answer": 0, "feedback": "U in rue steht für [y]."}, {"label": "roue (Rad): ou klingt hier …", "options": ["[y] ≈ ü", "[u] ≈ u", "[ɛ]"], "answer": 1, "feedback": "Ou in roue steht für [u]."}, {"label": "France und dans enthalten …", "options": ["[ɔ̃] wie in non", "[ɑ̃]", "ein zusätzliches deutliches ng"], "answer": 1, "feedback": "An/en wird in diesen Beispielen als Nasalvokal [ɑ̃] gesprochen."}], "why": "Rue [ʁy], roue [ʁu]; France und dans haben [ɑ̃]. Nasalität ist Teil des Vokals.", "support": "France = Frankreich; dans = in; non = nein; Lautzeichen sind Hilfen.", "hints": ["Prüfe zuerst die Aussageabsicht und die bereitgestellten Angaben.", "Löse die Felder einzeln und lies danach den ganzen Satz."], "lesson": "m9-l3", "section": "writing", "points": 3, "slotPoints": [1, 1, 1], "answerPattern": "rue: {0}; roue: {1}; France/dans: {2}", "id": "mock2-e16"}, {"type": "slots", "prompt": "Prüfe drei Regelentscheidungen zu c/ç und stummen Endungen.", "slots": [{"label": "garçon (Junge) braucht …", "options": ["cédille am c", "accent aigu am a", "keinen Zusatz"], "answer": 0, "feedback": "Ç erhält den s-Laut vor o."}, {"label": "c in café (Café) klingt hier …", "options": ["s", "k", "z"], "answer": 1, "feedback": "Vor a klingt c im Beispiel café wie k."}, {"label": "Das End-s in Paris ist normalerweise …", "options": ["ein deutliches s", "stumm", "ein zusätzliches n"], "answer": 1, "feedback": "Das s in Paris wird normalerweise nicht gesprochen."}], "why": "Garçon mit ç, café mit k-Laut; das End-s von Paris bleibt geschrieben, aber stumm.", "support": "Die richtigen Vorlagen garçon, café und Paris stehen absichtlich dabei.", "hints": ["Prüfe zuerst die Aussageabsicht und die bereitgestellten Angaben.", "Löse die Felder einzeln und lies danach den ganzen Satz."], "lesson": "m9-l4", "section": "writing", "points": 3, "slotPoints": [1, 1, 1], "answerPattern": "garçon: {0}; café: {1}; Paris: {2}", "id": "mock2-e17"}, {"type": "slots", "prompt": "Verbindung und Buchstabieren: drei Entscheidungen.", "slots": [{"label": "les amis (die Freunde) hat hier …", "options": ["eine z-Liaison", "eine t-Liaison", "nie eine Verbindung"], "answer": 0, "feedback": "Les + Vokalanfang amis wird hier mit z verbunden."}, {"label": "Nach et (und) gibt es …", "options": ["immer t-Liaison", "keine t-Liaison", "ein geschriebenes z"], "answer": 1, "feedback": "Et wird nicht mit t-Liaison angeschlossen."}, {"label": "G und J heißen …", "options": ["G = ji, J = gé", "G = gé, J = ji", "beide gé"], "answer": 1, "feedback": "G heißt gé, J heißt ji."}], "why": "Liaison verändert keine Schreibweise. Buchstabennamen sind nicht automatisch Laute im Wort.", "support": "Laut- und Schriftregeln aus M9, keine Audioaufgabe.", "hints": ["Prüfe zuerst die Aussageabsicht und die bereitgestellten Angaben.", "Löse die Felder einzeln und lies danach den ganzen Satz."], "lesson": "m9-l1", "section": "writing", "points": 3, "slotPoints": [1, 1, 1], "answerPattern": "les amis: {0}; et: {1}; Alphabet: {2}", "id": "mock2-e18"}, {"type": "open", "prompt": "Erkläre Émiles Nachricht auf Deutsch für eine Person, die kein Französisch lernt. Nenne Name/Alter, Herkunft/Wohnort, Klasse, Vorliebe/Ablehnung und die Orte mit Anzahl. Schreibe sinngemäß, keine Wort-für-Wort-Übersetzung.", "support": "Nutze die Szene oben. treize = 13; sixième B ≈ 6. Klasse B; la musique = Musik; le shopping = Einkaufen; deux musées = zwei Museen; une boulangerie = eine Bäckerei.", "sample": "Émile ist 13 Jahre alt, kommt aus Avignon und wohnt in Toulouse. Er geht in die 6. Klasse B, mag Musik, aber mag Einkaufen nicht. Im Viertel gibt es zwei Museen und eine Bäckerei.", "criteria": ["Name Émile und Alter 13 sind richtig wiedergegeben.", "Herkunft Avignon und Wohnort Toulouse sind richtig getrennt.", "Die Klasse sixième B ist sinngemäß wiedergegeben.", "Musik wird gemocht, Einkaufen abgelehnt.", "Zwei Museen und eine Bäckerei sind verständlich mit richtiger Anzahl genannt."], "why": "Das ist eine mögliche Fassung. Vergleiche deinen Text an den vier Kriterien. Die Selbstbewertung zählt getrennt von automatisch geprüften Antworten.", "rubric": [["Noch nicht erfüllt: Die geforderte Information fehlt oder ist inhaltlich unpassend.", "Ein Teil der geforderten Information ist verständlich.", "Die gesamte Information dieses Kriteriums ist verständlich und passend angegeben."], ["Noch nicht erfüllt: Die geforderte Information fehlt oder ist inhaltlich unpassend.", "Ein Teil der geforderten Information ist verständlich.", "Die gesamte Information dieses Kriteriums ist verständlich und passend angegeben."], ["Noch nicht erfüllt: Die geforderte Information fehlt oder ist inhaltlich unpassend.", "Ein Teil der geforderten Information ist verständlich.", "Die gesamte Information dieses Kriteriums ist verständlich und passend angegeben."], ["Noch nicht erfüllt: Die geforderte Information fehlt oder ist inhaltlich unpassend.", "Ein Teil der geforderten Information ist verständlich.", "Die gesamte Information dieses Kriteriums ist verständlich und passend angegeben."], ["Noch nicht erfüllt: Die geforderte Information fehlt oder ist inhaltlich unpassend.", "Ein Teil der geforderten Information ist verständlich.", "Die gesamte Information dieses Kriteriums ist verständlich und passend angegeben."]], "lesson": "m6-l4", "section": "text", "id": "mock2-e19", "language": "de"}, {"type": "open", "prompt": "Spiele Ana und schreibe einen kurzen französischen Vorstellungstext mit sechs bis acht Sätzen. Fakten: Name Ana; Alter 14; Herkunft Berlin; Wohnort Toulouse; Klasse sixième A; du magst Sport, aber keine Katzen. Im Viertel gibt es zwei Museen und eine Bäckerei. Verbinde die beiden Vorliebenangaben mit mais.", "support": "Bausteine: Je m’appelle; j’ai quatorze ans (14); je suis de; j’habite à; je suis en sixième A; le sport = Sport; les chats = Katzen; mais = aber; il y a = es gibt; deux musées = zwei Museen; une boulangerie = eine Bäckerei; et = und.", "sample": "Je m’appelle Ana. J’ai quatorze ans. Je suis de Berlin. J’habite à Toulouse. Je suis en sixième A. J’aime le sport, mais je n’aime pas les chats. Dans le quartier, il y a deux musées et une boulangerie.", "criteria": ["Name und Alter der Rolle Ana sind verständlich in Ich-Form genannt.", "Herkunft Berlin, Wohnort Toulouse und Klasse sixième A sind richtig getrennt.", "Sport ja und Katzen nein sind mit mais verbunden; n’ … pas ist vollständig.", "Il y a führt die Orte mit richtiger Anzahl und passenden bereitgestellten Gruppen ein.", "Der Text hängt verständlich zusammen; Person/Verb, Artikel, Apostrophe und Akzente wurden überprüft."], "why": "Das ist eine mögliche Fassung. Vergleiche deinen Text an den vier Kriterien. Die Selbstbewertung zählt getrennt von automatisch geprüften Antworten.", "rubric": [["Noch nicht erfüllt: Die geforderte Information fehlt oder ist inhaltlich unpassend.", "Nur Name oder Alter ist korrekt.", "Name und Alter stimmen; je m’appelle und j’ai … ans sind passend verwendet."], ["Noch nicht erfüllt: Die geforderte Information fehlt oder ist inhaltlich unpassend.", "Ein oder zwei der drei Angaben stimmen.", "Herkunft, Wohnort und Klasse stimmen mit passenden Bausteinen."], ["Noch nicht erfüllt: Die geforderte Information fehlt oder ist inhaltlich unpassend.", "Der Sinn ist teils klar, aber Verbinder oder ein Negationsteil fehlt.", "Beide Aussagen stimmen; mais, je n’aime pas und die bestimmten Artikel sind passend."], ["Noch nicht erfüllt: Die geforderte Information fehlt oder ist inhaltlich unpassend.", "Ein Ort oder seine Anzahl ist verständlich; andere Teile fehlen.", "Beide Orte stimmen; il y a bleibt gleich und die genauen Mengen sind passend."], ["Noch nicht erfüllt: Die geforderte Information fehlt oder ist inhaltlich unpassend.", "Weitgehend verständlich, aber mehrere Muster-/Schriftfehler erschweren das Lesen.", "Gut verständlicher Zusammenhang mit überwiegend passenden bekannten Formen und Schriftzeichen; kleinere Fehler sind möglich."]], "lesson": "m8-l4", "section": "text", "id": "mock2-e20", "language": "fr"}]}});D.version=6;})();
